#ifndef cellGcmInit
#define cellGcmInit(cmd_size, io_size, io_addr) \
    do { \
        static gcmContextData *_ctx = nullptr; \
        rsxInit(&_ctx, cmd_size, io_size, io_addr); \
        RenderDevice::gcmContext = _ctx; \
    } while (0)
#endif

